const rows = $input.all().map(i => i.json);
const cfg = {};
rows.forEach(r => { cfg[r.key] = r.value; });
return [{ json: cfg }];

const ci = $('Check CI').first()?.json;
const deploy = $('Check Deploy').first()?.json;
const shopify = $('Check Shopify').first()?.json;

const results = [];
const now = new Date().toISOString();

// CI status
let ciStatus = 'unknown', ciValue = 'no data';
if (ci?.workflow_runs?.length) {
  const run = ci.workflow_runs[0];
  ciStatus = run.conclusion === 'success' ? 'ok' : (run.conclusion === 'failure' ? 'error' : 'warn');
  ciValue = `${run.conclusion} (${run.name})`;
} else if (ci?.error) {
  ciStatus = 'error';
  ciValue = 'API unreachable';
}
results.push({ metric: 'ci_tests', value: ciValue, status: ciStatus, checked_at: now });

// Deploy status
let deployStatus = 'unknown', deployValue = 'no data';
if (deploy?.statusCode >= 200 && deploy?.statusCode < 400) {
  deployStatus = 'ok';
  deployValue = `HTTP ${deploy.statusCode}`;
} else if (deploy?.statusCode) {
  deployStatus = 'error';
  deployValue = `HTTP ${deploy.statusCode}`;
} else if (deploy?.error) {
  deployStatus = 'error';
  deployValue = 'unreachable';
}
results.push({ metric: 'deploy_health', value: deployValue, status: deployStatus, checked_at: now });

// Shopify status
let shopifyStatus = 'unknown', shopifyValue = 'no data';
if (shopify?.statusCode >= 200 && shopify?.statusCode < 400) {
  shopifyStatus = 'ok';
  shopifyValue = 'store accessible';
} else if (shopify?.statusCode) {
  shopifyStatus = 'warn';
  shopifyValue = `HTTP ${shopify.statusCode}`;
} else if (shopify?.error) {
  shopifyStatus = 'error';
  shopifyValue = 'store unreachable';
}
results.push({ metric: 'shopify_store', value: shopifyValue, status: shopifyStatus, checked_at: now });

return results.map(r => ({ json: r }));
